import { Component, Host, Prop, h } from "@stencil/core";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-nav-group",
	styleUrl: "nav-group.scss",
	shadow: true,
})
export class HbrNavGroup {
	/** collapsed state in side nav */
	@Prop({ reflect: true }) collapsed = false;
	render() {
		return (
			<Host role="group">
				<span
					class={{
						"nav-label": true,
						"nav-label--collapsed": this.collapsed,
					}}
					part="label"
				>
					<slot name="label" />
				</span>

				<slot />
			</Host>
		);
	}
}
